def transform(g,dbg=False):
    h,w=len(g),len(g[0])
    out=[r[:] for r in g]
    horiz=pos=None
    for i,r in enumerate(g):
        if r.count(2)==w: horiz=True; pos=i
    for j in range(w):
        if all(g[i][j]==2 for i in range(h)): horiz=False; pos=j
    from collections import Counter
    bg=Counter(c for r in g for c in r).most_common(1)[0][0]
    cells=[(i,j) for i in range(h) for j in range(w) if g[i][j] not in (bg,2)]
    col=g[cells[0][0]][cells[0][1]]
    for i,j in cells: out[i][j]=bg
    d=0
    if horiz:
        rows=[i for i,j in cells]; top,bot=min(rows),max(rows)
        if dbg: print('horiz',pos,'top,bot',top,bot)
        if top>pos:
            if top-1>pos: d=top-1-pos
            for i,j in cells: out[i-d][j]=col
            out[bot-d+1]=[8]*w
        else:
            if pos-1>bot: d=pos-1-bot
            for i,j in cells: out[i+d][j]=col
            out[top+d-1]=[8]*w
    else:
        cols=[j for i,j in cells]; left,right=min(cols),max(cols)
        if dbg: print('vert',pos,'l,r',left,right)
        if left>pos:
            if left-1>pos: d=left-1-pos
            for i,j in cells: out[i][j-d]=col
            for i in range(h): out[i][right-d+1]=8
        else:
            if pos-1>right: d=pos-1-right
            for i,j in cells: out[i][j+d]=col
            for i in range(h): out[i][left+d-1]=8
    return out
